### **Tool Class — `ApiTools.cs`**

```csharp
using ModelContextProtocol.Server;
using System.ComponentModel;
using System.Text.Json;

[McpServerToolType]
public class ApiTools(HttpClient httpClient, ILogger<ApiTools> logger)
{
    [McpServerTool, Description("Get a user by ID from the REST API.")]
    public async Task<string> GetUser(
        [Description("The numeric user ID")] int userId,
        CancellationToken cancellationToken = default)
    {
        logger.LogInformation("Fetching user {UserId}", userId);
        var json = await httpClient.GetStringAsync(
            $"https://jsonplaceholder.typicode.com/users/{userId}", cancellationToken);
        return json;
    }

    [McpServerTool, Description("List all posts, optionally filtered by user ID.")]
    public async Task<string> ListPosts(
        [Description("Optional user ID to filter posts")] int? userId = null,
        CancellationToken cancellationToken = default)
    {
        var url = "https://jsonplaceholder.typicode.com/posts";
        if (userId.HasValue)
            url += $"?userId={userId.Value}";

        logger.LogInformation("Listing posts (userId={UserId})", userId);
        var json = await httpClient.GetStringAsync(url, cancellationToken);

        // Return a summary instead of raw bulk JSON
        var posts = JsonSerializer.Deserialize<JsonElement>(json);
        return $"Found {posts.GetArrayLength()} posts.\n{json}";
    }

    [McpServerTool(ReadOnly = true), Description("Check if the API is reachable.")]
    public async Task<string> HealthCheck(CancellationToken cancellationToken = default)
    {
        var response = await httpClient.GetAsync(
            "https://jsonplaceholder.typicode.com/posts/1", cancellationToken);
        return response.IsSuccessStatusCode ? "API is healthy" : $"API returned {response.StatusCode}";
    }
}
```

